-- Generado por generar_semilla.py a partir del catálogo disponible en referencias/.
-- Contiene una sesión y un clip ficticios; no incluye registros privados.
BEGIN;
SET search_path TO pedagogia, public;

INSERT INTO curso (codigo, nombre) VALUES ('2ESO', '2.º ESO')
ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre;
INSERT INTO asignatura (codigo, nombre) VALUES ('MAT', 'Matemáticas')
ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre;
INSERT INTO curso_asignatura (curso_id, asignatura_id)
SELECT c.id, a.id FROM curso c CROSS JOIN asignatura a
WHERE c.codigo = '2ESO' AND a.codigo = 'MAT'
ON CONFLICT (curso_id, asignatura_id) DO NOTHING;

INSERT INTO alumno (sistema_origen, id_externo) VALUES ('fixture', 'alumno-demo-001')
ON CONFLICT (sistema_origen, id_externo) DO NOTHING;
INSERT INTO profesor (sistema_origen, id_externo) VALUES ('fixture', 'profesor-demo-001')
ON CONFLICT (sistema_origen, id_externo) DO NOTHING;

INSERT INTO sesion (sistema_origen, id_externo, alumno_id, profesor_id, curso_asignatura_id, manifest_actual)
SELECT 'fixture', 'sesion-demo-001', al.id, pr.id, ca.id,
  '{"fixture":true,"schemaVersion":"demo-1","originRecordId":"registro-demo-001","pedagogicalUnits":[{"id":"unidad-demo-001","sequence":1,"startSeconds":0,"endSeconds":60,"title":"Ejemplo ficticio de unidad","topic":"Contenido de muestra","objective":"Comprobar la importación del modelo"}]}'::jsonb
FROM alumno al CROSS JOIN profesor pr CROSS JOIN curso_asignatura ca
WHERE al.sistema_origen = 'fixture' AND al.id_externo = 'alumno-demo-001'
  AND pr.sistema_origen = 'fixture' AND pr.id_externo = 'profesor-demo-001'
  AND ca.curso_id = (SELECT id FROM curso WHERE codigo = '2ESO')
  AND ca.asignatura_id = (SELECT id FROM asignatura WHERE codigo = 'MAT')
ON CONFLICT (sistema_origen, id_externo) DO UPDATE SET
  alumno_id = EXCLUDED.alumno_id, profesor_id = EXCLUDED.profesor_id,
  curso_asignatura_id = EXCLUDED.curso_asignatura_id, manifest_actual = EXCLUDED.manifest_actual;

INSERT INTO clip (sesion_id, sistema_origen, id_externo, secuencia, inicio_segundos, fin_segundos, titulo, tema_principal, objetivo_aprendizaje, nombre_archivo_origen)
SELECT s.id, 'fixture', 'clip-demo-001', 1, 0, 60,
  'Clip de muestra', 'Contenido de muestra', 'Probar consulta del catálogo', 'clip-demo-001.mp4'
FROM sesion s WHERE s.sistema_origen = 'fixture' AND s.id_externo = 'sesion-demo-001'
ON CONFLICT (sistema_origen, id_externo) DO UPDATE SET
  sesion_id = EXCLUDED.sesion_id, secuencia = EXCLUDED.secuencia,
  inicio_segundos = EXCLUDED.inicio_segundos, fin_segundos = EXCLUDED.fin_segundos,
  titulo = EXCLUDED.titulo, tema_principal = EXCLUDED.tema_principal,
  objetivo_aprendizaje = EXCLUDED.objetivo_aprendizaje, nombre_archivo_origen = EXCLUDED.nombre_archivo_origen;

INSERT INTO version_catalogo_objetivos (curso_asignatura_id, codigo, version, estado, fecha_snapshot, alcance, proposito, completitud_declarada, metadatos_fuente)
VALUES ((SELECT ca.id FROM curso_asignatura ca JOIN curso c ON c.id = ca.curso_id JOIN asignatura a ON a.id = ca.asignatura_id WHERE c.codigo = '2ESO' AND a.codigo = 'MAT'), 'DESPEGA-MATH-2ESO-LT', '0.1', 'VALIDATED_FOR_EXPERIMENT', '2026-09-23'::date, 'Matemáticas — 2º ESO — catálogo experimental inicial', 'Unidades pedagógicas estables sobre las que acumular evidencia en el Motor Despega.', FALSE, '{"catalog_id":"DESPEGA-MATH-2ESO-LT","catalog_version":"0.1","status":"VALIDATED_FOR_EXPERIMENT","frozen_snapshot_date":"2026-09-23","scope":"Matemáticas — 2º ESO — catálogo experimental inicial","purpose":"Unidades pedagógicas estables sobre las que acumular evidencia en el Motor Despega.","completeness_claim":false,"governance":{"canonicalization_authority":"HUMAN_REVIEW / SYSTEM_OWNER","ai_self_validation_allowed":false,"silent_modification_allowed":false,"future_change_policy":"Cualquier cambio posterior debe generar una nueva versión del catálogo.","relationships_included":false,"learner_evidence_included":false,"curriculum_alignment_claimed":false,"source_of_truth_rule":"Este archivo representa el snapshot limpio v0.1. El espacio de descubrimiento/candidatos debe mantenerse separado."},"source_basis":[{"source_id":"SRC-BOOK-001","name":"Libro2ESO pdf Matemáticas.pdf","role":"educational source material"},{"source_id":"SRC-HUMAN-REVIEW-001","name":"Iterative human review in this conversation","role":"granularity refinement, recurring-error knowledge, approval of v0.1"}],"historical_lineage":{"bootstrap_first_pass":"CB-01 generated 117 first-pass candidates.","bootstrap_second_pass":"Second pass introduced conceptual microtargets, procedural microtargets, contextual modeling targets and transversal problem-solving targets.","legacy_candidate_ids_are_canonical":false,"legacy_to_v0_1_mapping":"Not frozen in this file because many legacy candidates were split or reorganized; no one-to-one mapping is asserted."},"validation_summary":{"target_count":308,"domain_count":19,"unique_ids":308,"duplicate_ids":[],"all_canonical_target_status":"VALIDATED_FOR_EXPERIMENT","relationships_count":0},"noncanonical_discovery_registry":[{"candidate_id":"CB01-LT-PCT-CHAIN-001","candidate_label":"Resolver variaciones porcentuales sucesivas mediante factores multiplicativos.","status":"PROPOSED_SCOPE_REVIEW","canonical":false,"reason":"Detectado en material suplementario de alcance/procedencia mixta; no incorporado al núcleo v0.1."}],"out_of_scope_or_not_yet_canonicalized":["Sistemas con tres incógnitas detectados en material adicional.","Funciones cuadráticas detectadas en hojas posteriores.","Hojas etiquetadas internamente como 1º ESO o 3º ESO que no se han promovido silenciosamente al núcleo 2º ESO.","Figuras/cuerpos adicionales de hojas de fórmulas fuera del núcleo prisma-pirámide-cilindro-cono.","Alineamiento con currículo oficial, programa del centro o requisitos de examen."]}'::jsonb)
ON CONFLICT (codigo, version) DO UPDATE SET estado = EXCLUDED.estado, fecha_snapshot = EXCLUDED.fecha_snapshot,
  alcance = EXCLUDED.alcance, proposito = EXCLUDED.proposito, completitud_declarada = EXCLUDED.completitud_declarada,
  metadatos_fuente = EXCLUDED.metadatos_fuente, curso_asignatura_id = EXCLUDED.curso_asignatura_id;

INSERT INTO dominio_objetivo (version_catalogo_id, codigo_externo, titulo, base_fuente, notas)
SELECT vc.id, src.codigo, src.titulo, src.base_fuente, src.notas
FROM version_catalogo_objetivos vc CROSS JOIN (VALUES
  ('PS', 'Resolución de problemas — capa transversal', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '["PS-004, PS-008 y PS-009 fueron reforzados explícitamente por feedback humano."]'::jsonb),
  ('DIV', 'Divisibilidad', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('INT', 'Números enteros', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '["LT-INT-005, LT-INT-009 y LT-INT-011 recogen refinamientos aportados por revisión humana."]'::jsonb),
  ('POW_ROOT_P10', 'Potencias, raíces y potencias de 10', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('FR_RAT', 'Fracciones y números racionales', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '["LT-FR-004, LT-FR-005, LT-FR-022, LT-FR-023 y LT-FR-025 recogen refinamientos explícitos surgidos del feedback humano."]'::jsonb),
  ('DEC', 'Números decimales', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('SEX', 'Sistema sexagesimal', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('ALG_POL', 'Álgebra, monomios y polinomios', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '["LT-ALG-008, LT-ALG-009 y LT-ALG-010 preservan explícitamente el error recurrente de combinar términos no semejantes señalado en revisión humana."]'::jsonb),
  ('EQ', 'Ecuaciones de primer y segundo grado', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('SYS', 'Sistemas de ecuaciones', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('PROP', 'Proporcionalidad', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('PCT', 'Porcentajes', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('FUNC', 'Funciones y funciones lineales', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('STAT', 'Estadística descriptiva', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('PROB', 'Probabilidad', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('PIT', 'Teorema de Pitágoras', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('SIM_TAL', 'Semejanza, escalas y teorema de Tales', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('GEO2D', 'Áreas y perímetros', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb),
  ('GEO3D', 'Cuerpos geométricos', '["Libro2ESO pdf Matemáticas.pdf","iterative human review in chat"]'::jsonb, '[]'::jsonb)
) AS src(codigo, titulo, base_fuente, notas)
WHERE vc.codigo = 'DESPEGA-MATH-2ESO-LT' AND vc.version = '0.1'
ON CONFLICT (version_catalogo_id, codigo_externo) DO UPDATE SET titulo = EXCLUDED.titulo, base_fuente = EXCLUDED.base_fuente, notas = EXCLUDED.notas;

