INSERT INTO entrada_catalogo_objetivo (version_catalogo_id, dominio_objetivo_id, objetivo_aprendizaje_id, id_objetivo_externo, etiqueta, tipo, estado)
SELECT vc.id, d.id, oa.id, src.id_externo, src.etiqueta, src.tipo, src.estado
FROM (VALUES
  ('PS', 'LT-PS-001', 'Comprender la situación descrita en un enunciado matemático antes de comenzar a operar.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-002', 'Identificar exactamente qué pregunta el problema y qué cantidad, objeto o incógnita debe obtenerse.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-003', 'Extraer y organizar los datos y condiciones proporcionados por el enunciado.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-004', 'Distinguir información relevante de información innecesaria para la resolución cuando ambas aparecen.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-005', 'Identificar las relaciones existentes entre los datos y aquello que se desea conocer.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-006', 'Traducir relaciones verbales o gráficas a una representación matemática adecuada.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-007', 'Construir una secuencia de operaciones o pasos que conecte los datos disponibles con lo solicitado.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-008', 'Interpretar qué representa un resultado intermedio dentro del contexto del problema.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-009', 'Determinar si un resultado intermedio responde ya a la pregunta o si todavía es necesario continuar operando.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-010', 'Interpretar el significado del resultado final respecto de la pregunta planteada.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-011', 'Comprobar que la solución obtenida es compatible con las condiciones originales del problema.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('PS', 'LT-PS-012', 'Expresar la respuesta final indicando correctamente referente, magnitud y unidad cuando corresponda.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-001', 'Reconocer cuándo una división es exacta, vinculándola con resto cero.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-002', 'Determinar si un número es divisor de otro mediante divisibilidad exacta.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-003', 'Determinar si un número es múltiplo de otro.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-004', 'Generar múltiplos de un número.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-005', 'Relacionar recíprocamente múltiplo y divisor.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-006', 'Enumerar los divisores de un número.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-007', 'Reconocer números primos a partir de sus divisores.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-008', 'Aplicar los criterios de divisibilidad presentados por el material.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-009', 'Descomponer un número en factores primos.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-010', 'Identificar divisores comunes de dos o más números.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-011', 'Identificar múltiplos comunes de dos o más números.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
  ('DIV', 'LT-DIV-012', 'Interpretar el m.c.d. como el mayor divisor común.', 'ATOMIC', 'VALIDATED_FOR_EXPERIMENT'),
