) AS src(id_relacion, id_origen, tipo, id_destino, estado, es_canonica, revision, prioridad, ancla, justificacion, notas)
JOIN version_catalogo_objetivos vc ON vc.codigo = 'DESPEGA-MATH-2ESO-LT' AND vc.version = '0.1'
JOIN conjunto_relaciones_objetivos cr ON cr.version_catalogo_id = vc.id AND cr.codigo = 'DESPEGA-MATH-2ESO-REL' AND cr.version = '0.1-CANDIDATE'
JOIN entrada_catalogo_objetivo origen ON origen.version_catalogo_id = vc.id AND origen.id_objetivo_externo = src.id_origen
JOIN entrada_catalogo_objetivo destino ON destino.version_catalogo_id = vc.id AND destino.id_objetivo_externo = src.id_destino
ON CONFLICT (conjunto_relaciones_id, id_relacion_externa) DO UPDATE SET entrada_origen_id = EXCLUDED.entrada_origen_id,
  tipo_relacion = EXCLUDED.tipo_relacion, entrada_destino_id = EXCLUDED.entrada_destino_id, estado = EXCLUDED.estado,
  es_canonica = EXCLUDED.es_canonica, requisito_revision = EXCLUDED.requisito_revision, prioridad_revision = EXCLUDED.prioridad_revision,
  ancla_fuente = EXCLUDED.ancla_fuente, justificacion = EXCLUDED.justificacion, notas = EXCLUDED.notas;

COMMIT;
